export function getExercisesForSelection(
  macroPart: BodyPartId,
  subRegion?: SubRegionId | null
): TherapeuticExercise[] {
  if (subRegion && SUB_REGION_INFO[subRegion]) {
    const family = SUB_REGION_INFO[subRegion].exerciseFamily;
    return EXERCISES_BY_FAMILY[family] || EXERCISES_BY_FAMILY.back;
  }
  const fallbackSub = DEFAULT_SUB_REGION_FOR_MACRO[macroPart];
  const family = SUB_REGION_INFO[fallbackSub].exerciseFamily;
  return EXERCISES_BY_FAMILY[family] || EXERCISES_BY_FAMILY.back;
}

/**
 * Returns localized anatomy data for the given sub-region across ro, en, sq, it, hr, rom.
 * Safely falls back to DEFAULT_LANG ("en") and base Romanian record.
 */
export function getLocalizedSubRegion(
  id: SubRegionId,
  lang: Lang = DEFAULT_LANG
): SubRegionInfo {
  const base = SUB_REGION_INFO[id];
  if (!base) return base;
  const loc = base.localized?.[lang];
  const override =
    lang === "ro" || lang === "en" || lang === "sq" || lang === "it"
      ? LITERACY_OVERRIDES[id]?.[lang]
      : undefined;
  if (!loc && !override) {
    return {
      ...base,
      summary: cleanAnatomySummary(base.summary),
    };
  }
  return {
    ...base,
    label: override?.label ?? loc?.label ?? base.label,
    tissueLabel: override?.tissueLabel ?? loc?.tissueLabel ?? base.tissueLabel,
    systemLabel: override?.systemLabel ?? loc?.systemLabel ?? base.systemLabel,
    summary: cleanAnatomySummary(override?.summary ?? loc?.summary ?? base.summary),
    functionDescription:
      override?.functionDescription ?? loc?.functionDescription ?? base.functionDescription,
    clinicalNotes: override?.clinicalNotes ?? loc?.clinicalNotes ?? base.clinicalNotes,
    commonConditions: override?.commonConditions ?? loc?.commonConditions ?? base.commonConditions,
    recommendedSpecialty:
      override?.recommendedSpecialty ?? loc?.recommendedSpecialty ?? base.recommendedSpecialty,
    searchKeywords: loc?.searchKeywords ?? base.searchKeywords,
  };
}
